                };
                g = Tracked(new_ll);
            }
        );
        let new_ll = LL {
            first: res,
            data: Ghost(ll.data@),
            perms: Tracked(ll.perms.get()),
        };

        assert(forall |i: nat| ll.valid_node(i, ll.next_ptr(i))
            ==> new_ll.valid_node(i, new_ll.next_ptr(i)));

        new_ll
    }
